"""Observe Java object identity and state transitions, without expected answers."""
from harness_random04 import uniform_parts
CORE=r'''
class Nodes4 {
record Snapshot(RandomNode root,ArrayList<RandomNode> nodes,ArrayList<Integer> data,ArrayList<RandomNode> left,ArrayList<RandomNode> right,ArrayList<Integer> values,IdentityHashMap<RandomNode,Integer> rank){}
static void check(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
static Snapshot take(RandomBst actor){var root=actor.Root;var pending=new ArrayDeque<RandomNode>();if(root!=null)pending.push(root);var nodes=new ArrayList<RandomNode>();var data=new ArrayList<Integer>();var left=new ArrayList<RandomNode>();var right=new ArrayList<RandomNode>();var seen=new IdentityHashMap<RandomNode,Boolean>();while(!pending.isEmpty()){var node=pending.pop();check(!seen.containsKey(node)&&nodes.size()<1000,"Root must be a finite proper tree");seen.put(node,true);nodes.add(node);data.add(node.Data);left.add(node.Left);right.add(node.Right);if(node.Right!=null)pending.push(node.Right);if(node.Left!=null)pending.push(node.Left);}var ordered=new ArrayList<RandomNode>();var stack=new ArrayDeque<RandomNode>();var current=root;while(current!=null||!stack.isEmpty()){while(current!=null){stack.push(current);current=current.Left;}current=stack.pop();ordered.add(current);current=current.Right;}var values=new ArrayList<Integer>();var rank=new IdentityHashMap<RandomNode,Integer>();for(var node:ordered){check(values.isEmpty()||values.get(values.size()-1)<=node.Data,"Maintain BST inorder");rank.put(node,values.size());values.add(node.Data);}return new Snapshot(root,nodes,data,left,right,values,rank);}
static JsonArray query(RandomBst actor,Snapshot before,RandomNode node){check(actor.Root==before.root(),"Queries preserve Root");for(int i=0;i<before.nodes().size();++i){var old=before.nodes().get(i);check(old.Data==before.data().get(i)&&old.Left==before.left().get(i)&&old.Right==before.right().get(i),"Queries preserve Data and links");}check(node==null||before.rank().containsKey(node),"Return actual current node");return node==null?new JsonArray():new JsonArray().add(node.Data);}
static JsonValue basic(RandomBst actor,String operation,JsonArray args){switch(operation){case "Insert":actor.Insert(args.get(0).asInt());return Json.NULL;case "Delete":return Json.value(actor.Delete(args.get(0).asInt()));case "Find":return query(actor,take(actor),actor.Find(args.get(0).asInt()));case "GetRandomNode":return query(actor,take(actor),actor.GetRandomNode());default:throw new IllegalArgumentException("Unknown operation");}}
static JsonObject delta(ArrayList<Integer> before,ArrayList<Integer> after){int i=0,j=0;var added=new JsonArray();var removed=new JsonArray();while(i<before.size()&&j<after.size()){int a=before.get(i),b=after.get(j);if(a==b){++i;++j;}else if(a<b)removed.add(before.get(i++));else added.add(after.get(j++));}while(i<before.size())removed.add(before.get(i++));while(j<after.size())added.add(after.get(j++));return new JsonObject().add("added",added).add("removed",removed).add("count",after.size());}
static JsonArray operations,arguments;static ArrayList<Integer> values;
static RandomBst build(){var actor=new RandomBst();for(int i=1;i<operations.size();++i)basic(actor,operations.get(i).asString(),arguments.get(i).asArray());return actor;}
static JsonValue run(JsonObject row)throws Exception{var args=row.get("arguments").asArray();var ops=args.get(0).asArray();var argv=args.get(1).asArray();long[] seed={0x411b57};RandomSource.Draw=(lower,upper)->{check(0<=lower&&lower<=upper,"Use valid inclusive bounds");seed[0]=(seed[0]*1664525+1013904223)&0xffffffffL;return lower+(int)((seed[0]*((long)upper-lower+1))>>>32);};check(RandomBst.class.getMethod("Insert",int.class).getReturnType()==void.class&&RandomBst.class.getMethod("Delete",int.class).getReturnType()==boolean.class&&RandomBst.class.getMethod("Find",int.class).getReturnType()==RandomNode.class&&RandomBst.class.getMethod("GetRandomNode").getReturnType()==RandomNode.class,"Use declared result types");var actor=new RandomBst();var before=take(actor);var results=new JsonArray().add(Json.NULL);var changes=new JsonArray().add(delta(new ArrayList<>(),before.values()));for(int i=1;i<ops.size();++i){String operation=ops.get(i).asString();if(operation.equals("GetRandomNode")){operations=new JsonArray();arguments=new JsonArray();for(int j=0;j<i;++j){operations.add(ops.get(j));arguments.add(argv.get(j));}values=new ArrayList<>(before.values());var saved=RandomSource.Draw;var labels=new JsonArray();for(int j=0;j<values.size();++j)labels.add(j);try{RandomAudit4_11.run(new JsonObject().add("arguments",new JsonArray().add(labels)));}finally{RandomSource.Draw=saved;}check(actor.Root==before.root(),"Instances own independent state");}results.add(basic(actor,operation,argv.get(i).asArray()));var after=take(actor);changes.add(delta(before.values(),after.values()));before=after;}var finalValues=new JsonArray();for(int value:before.values())finalValues.add(value);return new JsonObject().add("actual",new JsonObject().add("results",results).add("finalValues",finalValues)).add("changes",changes).add("mutationOk",true).add("uniformOk",true);}
}
class Solution_4_11 {RandomBst actor;public void Shuffle(int[] array){if(actor==null)actor=Nodes4.build();var before=Nodes4.take(actor);Nodes4.check(before.values().equals(Nodes4.values)&&array.length==before.values().size(),"Preserve operation-prefix multiset");var chosen=actor.GetRandomNode();Nodes4.query(actor,before,chosen);if(array.length==0){Nodes4.check(chosen==null,"Empty query returns null");return;}Nodes4.check(chosen!=null,"Nonempty query returns current node");int selected=before.rank().get(chosen);var remaining=new ArrayList<Integer>();for(int i=0;i<array.length;++i)if(i!=selected)remaining.add(i);for(int i=remaining.size()-1;i>0;--i)Collections.swap(remaining,i,RandomSource.GetRandom(0,i));array[0]=selected;for(int i=0;i<remaining.size();++i)array[i+1]=remaining.get(i);}}
'''
def parts(code):
    outside,inside=uniform_parts('java',code+CORE)
    return outside,'static JsonValue executeRandomBst4(JsonObject row){try{return Nodes4.run(row);}catch(RuntimeException error){throw error;}catch(Exception error){throw new RuntimeException(error);}}\n'
